Content.Example:
start:
WriteLine("Color : ");
string Color = ReadLine().ToLower();// ToLower() -> تمام کاراکترهای یک عبارت را به حروف کوچک تبدیل میکند

switch (Color)
{
case "red": WriteLine("Stop"); break;
case "green": WriteLine("Go"); break;
case "yellow": WriteLine("Slow"); break;
default: WriteLine("Alarm"); break;
}

goto start;

