while (low <= high)
{
int mid = (low + high) / 2;

if (usernum == number[mid])
{
  WriteLine($"number found in : {mid} index");
  return;
}
else if (usernum < number[mid])
  high = mid - 1;
else
  low = mid + 1;
}
WriteLine("not found");

